/**
 Do not return anything, modify board in-place instead.
 */
function gameOfLife(board: number[][]): void {
  const m = board.length;
  const n = board[0].length;

  // Кодируем два поколения в одной клетке:
  //   бит 0 (value & 1) — текущее состояние,
  //   бит 1 (value & 2) — следующее состояние.
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      // Считаем живых соседей по СТАРОМУ состоянию (бит 0)
      let live = 0;
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if (dr === 0 && dc === 0) continue; // саму клетку не считаем
          const nr = r + dr;
          const nc = c + dc;
          if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
            live += board[nr][nc] & 1;
          }
        }
      }

      const alive = (board[r][c] & 1) === 1;
      // Живая выживает при 2 или 3 соседях, мёртвая оживает при ровно 3
      if ((alive && (live === 2 || live === 3)) || (!alive && live === 3)) {
        board[r][c] |= 2; // следующее состояние — живая
      }
    }
  }

  // Переходим к новому поколению: сдвигаем бит 1 на место бита 0
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      board[r][c] >>= 1;
    }
  }
}

// Время: O(m · n) — для каждой клетки смотрим 8 соседей
// Память: O(1) — новое состояние хранится в той же клетке
